# Batch drills ("list of computations in one task"): up to 3 representative items -> single-question tasks.
from fractions import Fraction as Fr
SPLIT = {}
def P(q, k, d, yn=False): return {"q": q, "k": k, "d": d, "yesno": yn}
def T(parent, why, parts): SPLIT[parent] = {"why": why, "parts": parts}
B = "пачка из нескольких однотипных вычислений в одной задаче с выбором ответа (ответ угадывался сравнением вариантов, время ученика — на все пункты сразу); оставлены характерные пункты, каждый — отдельная задача"

def piF(f):  # LaTeX of f*pi, f Fraction
    s = "-" if f < 0 else ""; f = abs(f)
    if f.denominator == 1: return s + ("\\pi" if f.numerator == 1 else "%d\\pi" % f.numerator)
    num = "\\pi" if f.numerator == 1 else "%d\\pi" % f.numerator
    return "%s\\dfrac{%s}{%d}" % (s, num, f.denominator)

def d2r(deg, stem="Выразите в радианной мере величину угла"):
    f = Fr(deg, 180); key = "$%s$" % piF(f)
    inv = Fr(180, deg) if deg else None
    cands = [("$%s$" % piF(Fr(deg, 360)), "Ученик разделил на $360^{\\circ}$ вместо $180^{\\circ}$: $%d^{\\circ}=\\dfrac{%d}{180}\\pi=%s$." % (deg, deg, piF(f))),
             ("$%s$" % piF(inv), "Ученик перевернул отношение: $\\dfrac{180}{%d}\\pi$; верно $\\dfrac{%d}{180}\\pi=%s$." % (deg, deg, piF(f))) if inv and inv != f else None,
             ("$%s%s$" % ("-" if f < 0 else "", ("\\dfrac{%d}{%d}" % (abs(f.numerator), f.denominator)) if f.denominator != 1 else "%d" % abs(f.numerator)), "Ученик потерял множитель $\\pi$: $%d^{\\circ}=\\dfrac{%d}{180}\\pi$." % (deg, deg)),
             ("$%s$" % piF(Fr(deg, 90)), "Ученик разделил на $90^{\\circ}$ вместо $180^{\\circ}$.")]
    d, seen = [], {key}
    for c in cands:
        if c and c[0] not in seen: seen.add(c[0]); d.append(c)
    return P(r"%s $%d^{\circ}$." % (stem, deg), key, d[:3])

def degs(x):
    x = Fr(x)
    if x.denominator == 1: return r"%d^{\circ}" % x
    return (r"%s^{\circ}" % (("%.4f" % float(x)).rstrip("0").rstrip(".").replace(".", "{,}")))
def r2d(f, stem="Выразите в градусной мере величину угла"):
    deg = f * 180; key = "$%s$" % degs(deg)
    cands = [("$%s$" % degs(f * 360), r"Ученик заменил $\pi$ на $360^{\circ}$; $\pi$ радиан — это $180^{\circ}$: $%s=%s$." % (piF(f), degs(deg))),
             ("$%s$" % degs(f * 90), r"Ученик заменил $\pi$ на $90^{\circ}$; $\pi$ радиан — это $180^{\circ}$."),
             ("$%s$" % degs(-deg), r"Ученик потерял знак минус: угол $%s$ отрицательный." % piF(f)) if deg < 0 else ("$%s$" % degs(180 - deg), r"Ученик нашёл угол, дополняющий данный до $180^{\circ}$, а не сам угол: $%s=%s$." % (piF(f), degs(deg))),
             ("$%s$" % degs(deg + 180), r"Ученик прибавил лишние $180^{\circ}$: $%s=%s$." % (piF(f), degs(deg)))]
    d, seen = [], {key}
    for v, w in cands:
        if v not in seen: seen.add(v); d.append((v, w))
    return P(r"%s $%s$." % (stem, piF(f)), key, d[:3])

