def adj_r(deg):
    f = Fr(180 - deg, 180)
    return P(r"Найдите радианную меру угла, смежного с углом $%d^{\circ}$." % deg, "$%s$" % piF(f), [
        ("$%s$" % piF(Fr(deg, 180)), r"Ученик перевёл в радианы сам угол $%d^{\circ}$, а нужен смежный: $180^{\circ}-%d^{\circ}=%d^{\circ}$." % (deg, deg, 180 - deg)),
        ("$%s$" % piF(Fr(90 - deg, 180)), r"Ученик нашёл дополнительный угол ($90^{\circ}-%d^{\circ}$) вместо смежного ($180^{\circ}-%d^{\circ}$)." % (deg, deg)) if 90 - deg != deg else ("$%s$" % piF(Fr(270 - deg, 180)), r"Ученик вычел из $270^{\circ}$ вместо $180^{\circ}$: смежные углы в сумме дают $180^{\circ}$."),
        ("$%s$" % piF(Fr(360 - deg, 180)), r"Ученик вычел из $360^{\circ}$ вместо $180^{\circ}$: смежные углы в сумме дают $180^{\circ}$.")])
T("G10_TB_§14_14_15", B, [adj_r(30), adj_r(45), adj_r(60)])
def adj_d(f):
    return P(r"Найдите градусную меру угла, смежного с углом $%s$." % piF(f), r"$%d^{\circ}$" % (180 - f * 180), [
        (r"$%d^{\circ}$" % (f * 180), r"Ученик перевёл в градусы сам угол, а нужен смежный: $180^{\circ}-%d^{\circ}$." % (f * 180)),
        (r"$%d^{\circ}$" % (90 - f * 180), r"Ученик нашёл дополнительный угол ($90^{\circ}-%d^{\circ}$) вместо смежного." % (f * 180)) if 90 - f * 180 != f * 180 else (r"$%d^{\circ}$" % (270 - f * 180), r"Ученик вычел из $270^{\circ}$ вместо $180^{\circ}$: смежные углы в сумме дают $180^{\circ}$."),
        (r"$%d^{\circ}$" % (360 - f * 180), r"Ученик вычел из $360^{\circ}$ вместо $180^{\circ}$.")])
