MILK = r"В опросе $50$ наугад выбранных покупателей о предпочитаемой жирности молока получены частоты: $0\%$ — $10$; $0{,}5\%$ — $6$; $1\%$ — $4$; $1{,}5\%$ — $5$; $2{,}5\%$ — $12$; $3{,}2\%$ — $7$; $5\%$ — $6$. Молокозавод выпускает $2000$ л молока в день. Сколько литров молока жирностью $FAT$ рекомендуется выпускать, если выборка репрезентативна?"
def milk(fat, fr, pct):
    v = 2000 * fr // 50
    return P(MILK.replace("FAT", fat), r"$%d$ л" % v, [
        (r"$%d$ л" % (2000 * fr // 100), r"Ученик разделил на $100$, а в опросе $50$ человек: доля равна $\dfrac{%d}{50}$." % fr),
        (r"$%d$ л" % (fr * 10), r"Ученик умножил частоту на $10$, не находя долю от $2000$ л."),
        (r"$%s$ л" % pct, r"Ученик взял процент жирности вместо доли покупателей: $2000\cdot %s\%%$; доля покупателей равна $\dfrac{%d}{50}$." % (fat.replace("\\%", ""), fr))])
T("G11_TB_23_2_23_2_1", "семь видов молока в одной задаче с выбором ответа: ответ угадывался сравнением вариантов", [milk(r"0\%", 10, "0"), milk(r"2{,}5\%", 12, "50"), milk(r"5\%", 6, "100")])

