TG = r"Дана функция $f(x)=x^{2}$. Найдите тангенс угла наклона касательной к её графику в точке с абсциссой $x=%d$."
def tg(x):
    key = r"$%d$" % (2 * x)
    xs = ("(%d)" % x) if x < 0 else str(x)
    cands = [(r"$%d$" % (x * x), r"Ученик вычислил значение функции $f(%d)=%d$, а тангенс угла наклона касательной равен производной $f'(%d)=2\cdot%s$." % (x, x * x, x, xs)),
             (r"$%d$" % x, r"Ученик не умножил на $2$: $f'(x)=2x$."),
             (r"$%d$" % (-2 * x), r"Ученик ошибся в знаке: $f'(%d)=2\cdot%s=%d$." % (x, xs, 2 * x)),
             (r"$\dfrac{%d}{2}$" % x if x % 2 else r"$%d$" % (x // 2), r"Ученик разделил на $2$ вместо умножения: $f'(x)=2x$.")]
    if x == 0:
        cands = [(r"$1$", r"Ученик решил, что касательная к параболе в вершине наклонена под углом $45^{\circ}$; в вершине она горизонтальна, $f'(0)=0$."),
                 (r"$2$", r"Ученик взял коэффициент $2$ из $f'(x)=2x$, не подставив $x=0$."),
                 (r"не существует", r"Ученик решил, что в вершине производной нет; функция гладкая, $f'(0)=0$.")]
    d, seen = [], {key}
    for v, w in cands:
        if v not in seen: seen.add(v); d.append((v, w))
    return P(TG % x, key, d[:3])
